  const lines = [
    '@echo off',
    'set TARGET=staging',
    'echo Deploying to %TARGET%',
    'call build.cmd %TARGET%',
    'if errorlevel 1 exit /b 1',
    'echo Done',
  ];
  const content = lines.join('\r\n') + '\r\n';
  return { content, codes: Array.from(content).map(c => c.charCodeAt(0)).filter(c => c === 13 || c === 10).join(',') };
}"}

